"use strict";(self.webpackChunkgf_site=self.webpackChunkgf_site||[]).push([["1924"],{55226(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"v0.1.x(Latest)","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"quickSidebar":[{"type":"link","href":"/quick/overview","label":"Overview","docId":"quick/overview","unlisted":false},{"type":"link","href":"/quick/environment","label":"Environment Setup","docId":"quick/environment","unlisted":false},{"type":"link","href":"/quick/installation","label":"Installation","docId":"quick/installation","unlisted":false},{"type":"link","href":"/quick/have-a-try","label":"Try It Out","docId":"quick/have-a-try","unlisted":false}],"docsSidebar":[{"type":"category","label":"Design Principles","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/ai-native","label":"AI-Native Design","docId":"docs/concepts/ai-native","unlisted":false},{"type":"link","href":"/docs/modular-design","label":"Modular Design","docId":"docs/concepts/modular-design","unlisted":false},{"type":"link","href":"/docs/spec-driven-development","label":"AI Spec-Driven Development","docId":"docs/concepts/spec-driven-development","unlisted":false}],"href":"/docs/concepts"},{"type":"category","label":"Architecture Overview","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/core-host","label":"Core Host Service","docId":"docs/architecture/core-host","unlisted":false},{"type":"link","href":"/docs/admin-workspace","label":"Default Management Workspace","docId":"docs/architecture/admin-workspace","unlisted":false},{"type":"link","href":"/docs/plugin-system","label":"Dual-Mode Plugin System","docId":"docs/architecture/plugin-system","unlisted":false},{"type":"link","href":"/docs/distributed-architecture","label":"Native Distributed Architecture","docId":"docs/architecture/distributed-architecture","unlisted":false}],"href":"/docs/architecture"},{"type":"category","label":"Features","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/configuration","label":"Configuration","docId":"docs/features/configuration","unlisted":false},{"type":"link","href":"/docs/api-reference","label":"API Reference","docId":"docs/features/api-reference","unlisted":false},{"type":"link","href":"/docs/multi-tenant","label":"Multi-Tenancy","docId":"docs/features/multi-tenant","unlisted":false},{"type":"link","href":"/docs/scheduled-tasks","label":"Scheduled Tasks","docId":"docs/features/scheduled-tasks","unlisted":false},{"type":"link","href":"/docs/plugin-management","label":"Plugin Management","docId":"docs/features/plugin-management","unlisted":false},{"type":"link","href":"/docs/i18n","label":"Internationalization (I18N)","docId":"docs/features/i18n","unlisted":false}],"href":"/docs/features"},{"type":"category","label":"Plugin Development","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/source-plugins","label":"Source Plugins","docId":"docs/plugin-development/source-plugins","unlisted":false},{"type":"link","href":"/docs/wasm-plugins","label":"Dynamic Plugins (WASM)","docId":"docs/plugin-development/wasm-plugins","unlisted":false}],"href":"/docs/plugin-development"},{"type":"category","label":"Dev Tools","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/commands","label":"Dev Commands","docId":"docs/tools/commands","unlisted":false},{"type":"link","href":"/docs/agent-skills","label":"Dev Skills","docId":"docs/tools/agent-skills","unlisted":false}],"href":"/docs/tools"}],"communitySidebar":[{"type":"link","href":"/community","label":"Community","docId":"community/community","unlisted":false},{"type":"link","href":"/community/support","label":"Support Us","docId":"community/support","unlisted":false}]},"docs":{"community/community":{"id":"community/community","title":"Community","description":"Official LinaPro community channels \u2014 QQ groups, WeChat, Discord, and GitHub Issues \u2014 with guidance on which channel is best for real-time discussion, reproducible bugs, feature requests, documentation feedback, and plugin development questions.","sidebar":"communitySidebar"},"community/support":{"id":"community/support","title":"Support Us","description":"Practical ways to support the long-term maintenance of LinaPro, including filing reproducible issues, improving documentation, sharing production experience, joining community discussions, and donating through WeChat Pay or Alipay. Please include your GitHub or Gitee account name in the donation note so we can keep an accurate donation record.","sidebar":"communitySidebar"},"docs/architecture/admin-workspace":{"id":"docs/architecture/admin-workspace","title":"Default Management Workspace","description":"A comprehensive look at lina-vben, the LinaPro default management workspace \u2014 its functional modules, technology stack, and design characteristics, covering access control, system settings, job scheduling, multi-tenant management, organization management, content management, system monitoring, extension center, and developer center, as well as the dynamic menu injection mechanism for plugins.","sidebar":"docsSidebar"},"docs/architecture/architecture":{"id":"docs/architecture/architecture","title":"Architecture Overview","description":"A detailed breakdown of LinaPro architecture \u2014 the responsibilities, runtime relationships, and design principles of the five layers: core host service, management workspace, dual-mode plugin system, AI development workflow, and AI skill system. Understand the layered model, loose-coupling approach, and how each component collaborates to deliver business features.","sidebar":"docsSidebar"},"docs/architecture/core-host":{"id":"docs/architecture/core-host","title":"Core Host Service","description":"A detailed look at lina-core, the LinaPro core host service \u2014 the API layer, business service layer, plugin runtime, governance services (JWT auth, RBAC, operation logs, session management), scheduled task subsystem, i18n runtime, and the stable extension seams and event hook system exposed to plugins.","sidebar":"docsSidebar"},"docs/architecture/distributed-architecture":{"id":"docs/architecture/distributed-architecture","title":"Native Distributed Architecture","description":"How LinaPro natively supports distributed deployment \u2014 single-node vs. cluster mode, Raft-style distributed leader election, node roles and horizontal scaling, permission topology version synchronization, distributed locks and cluster-aware key-value cache, and how to enable cluster mode with zero code changes.","sidebar":"docsSidebar"},"docs/architecture/plugin-system":{"id":"docs/architecture/plugin-system","title":"Dual-Mode Plugin System","description":"A comprehensive look at the LinaPro dual-mode plugin system \u2014 official plugin submodules, source plugins vs. WASM dynamic plugins, the plugin lifecycle (install, enable, disable, uninstall), isolation mechanisms (database namespace, tenant_id filtering, file namespace, WASM sandbox), multi-tenant plugin manifest fields, host-plugin boundary rules, and the extension point system.","sidebar":"docsSidebar"},"docs/concepts/ai-native":{"id":"docs/concepts/ai-native","title":"AI-Native Design","description":"A detailed look at LinaPro as an AI-native framework \u2014 what AI-native truly means, how it differs from AI-assisted development, how AI participates in every stage of the development lifecycle, the built-in AI skill system covering backend, frontend, testing, performance auditing, and version management, and why spec-driven development prevents architectural drift over time.","sidebar":"docsSidebar"},"docs/concepts/concepts":{"id":"docs/concepts/concepts","title":"Design Principles","description":"An introduction to the core design principles behind LinaPro \u2014 AI-native design, modular architecture, and AI spec-driven development \u2014 helping developers build the right mental model before going deeper into the framework.","sidebar":"docsSidebar"},"docs/concepts/modular-design":{"id":"docs/concepts/modular-design","title":"Modular Design","description":"An exploration of LinaPro modular design \u2014 how domain-bounded built-in capabilities, first-class plugin system, stable extension seams, and lifecycle-managed modules let developers assemble systems from proven building blocks rather than building everything from scratch.","sidebar":"docsSidebar"},"docs/concepts/spec-driven-development":{"id":"docs/concepts/spec-driven-development","title":"AI Spec-Driven Development","description":"A detailed guide to LinaPro Specification-Driven Development (SDD) and the OpenSpec workflow \u2014 the five-stage development loop (explore, propose, implement, review, archive), the responsibilities of AI and humans at each stage, the OpenSpec directory structure and spec file formats, and how spec anchors and mandatory E2E tests prevent architectural drift.","sidebar":"docsSidebar"},"docs/features/api-reference":{"id":"docs/features/api-reference","title":"API Reference","description":"How LinaPro automatically aggregates host and plugin API documentation \u2014 the OpenAPI endpoint, in-workspace API explorer, the declarative interface definition model, RBAC permission integration, multi-language API doc translation, in-browser debugging, and how to import the spec into Apifox, Postman, and other tools.","sidebar":"docsSidebar"},"docs/features/configuration":{"id":"docs/features/configuration","title":"Configuration","description":"A detailed guide to the LinaPro core host service configuration file config.yaml, covering HTTP server, logging, PostgreSQL default database, JWT authentication, session management, scheduled tasks, internationalization (built-in en-US and zh-CN only), Redis cluster coordination, file uploads, and plugin governance \u2014 everything you need to tune the framework runtime behavior.","sidebar":"docsSidebar"},"docs/features/features":{"id":"docs/features/features","title":"Features","description":"An overview of LinaPro framework features, covering runtime locale file structure and format, how to add new languages, plugin internationalization resource organization, API documentation multi-language translation, runtime translation cache invalidation, and the frontend language switcher \u2014 everything you need to build a globally accessible multi-language application.","sidebar":"docsSidebar"},"docs/features/i18n":{"id":"docs/features/i18n","title":"Internationalization (I18N)","description":"An overview of LinaPro internationalization support, including the built-in language packs, runtime locale file structure and format, how to add new languages, plugin internationalization resource organization, API documentation multi-language translation, runtime translation cache invalidation, and the frontend language switcher \u2014 everything you need to build a globally accessible multi-language application.","sidebar":"docsSidebar"},"docs/features/multi-tenant":{"id":"docs/features/multi-tenant","title":"Multi-Tenancy","description":"An overview of LinaPro multi-tenancy capabilities, including the host built-in bizctx request context, tenant_id filtering seam, default tenant_id = 0 platform tenant mode, the official multi-tenant source plugin for tenant lifecycle and membership management, plugin multi-tenant manifest fields, global vs. tenant-scoped plugin enablement, LifecycleGuard protection, and the boundaries of the current Pool shared-database model.","sidebar":"docsSidebar"},"docs/features/plugin-management":{"id":"docs/features/plugin-management","title":"Plugin Management","description":"A practical guide to daily LinaPro plugin operations, including how to configure plugin sources in hack/config.yaml, use make commands to install, upgrade, and check plugin status, filter target plugins with p and source parameters, force-overwrite local changes, and perform plugin enablement, disablement, and uninstallation through the management workspace UI.","sidebar":"docsSidebar"},"docs/features/scheduled-tasks":{"id":"docs/features/scheduled-tasks","title":"Scheduled Tasks","description":"A detailed guide to the LinaPro scheduled task subsystem, covering cron expression configuration, task types (Go handlers and shell commands), group management, execution logs and error inspection, cluster-mode distributed scheduling with deduplication, and how to register custom cron handlers in source plugins.","sidebar":"docsSidebar"},"docs/plugin-development/plugin-development":{"id":"docs/plugin-development/plugin-development","title":"Plugin Development","description":"An overview of LinaPro dual-mode plugin system design \u2014 when to choose source plugins vs. WASM dynamic plugins, a detailed feature comparison, selection guidance, and the unique value of dynamic plugins for hot-loading, production hotfixes, and commercial distribution.","sidebar":"docsSidebar"},"docs/plugin-development/source-plugins":{"id":"docs/plugin-development/source-plugins","title":"Source Plugins","description":"A complete guide to developing LinaPro source plugins, covering directory structure conventions, the official plugin submodule workspace, interface definitions, PostgreSQL installation SQL, multi-tenant manifest fields, database and file access isolation, lifecycle hook registration, frontend page integration, menu and permission declarations, and the plugin version upgrade workflow.","sidebar":"docsSidebar"},"docs/plugin-development/wasm-plugins":{"id":"docs/plugin-development/wasm-plugins","title":"Dynamic Plugins (WASM)","description":"A complete guide to developing LinaPro WASM dynamic plugins, covering directory structure, cross-platform linactl builds, host service bridge interfaces (runtime, cron, storage, network, data), hostServices permission declarations in the plugin manifest, multi-tenant manifest fields, runtime upload and installation workflow, and key differences from source plugins.","sidebar":"docsSidebar"},"docs/tools/agent-skills":{"id":"docs/tools/agent-skills","title":"Dev Skills","description":"A complete guide to LinaPro AI skills \u2014 the optional OpenSpec CLI, goframe-v2, and find-skills that can be installed externally, plus 13 project-bundled skills covering frontend design, Git workflows, code review, E2E testing, and performance auditing. Includes installation instructions and usage guidance for every skill.","sidebar":"docsSidebar"},"docs/tools/commands":{"id":"docs/tools/commands","title":"Dev Commands","description":"A complete reference for the cross-platform dev command set in the LinaPro project \u2014 covering linactl, Makefile compatibility entry, Windows make.cmd wrapper, dev server management, full builds, WASM plugin builds, Docker image builds, testing, i18n validation, plugin tools, and database initialization on macOS, Linux, and Windows.","sidebar":"docsSidebar"},"docs/tools/tools":{"id":"docs/tools/tools","title":"Dev Tools","description":"An overview of the developer tooling built into LinaPro \u2014 covering every make command with usage examples, and the full AI skills library for frontend design, code review, testing, performance auditing, and OpenSpec workflows.","sidebar":"docsSidebar"},"quick/environment":{"id":"quick/environment","title":"Environment Setup","description":"This guide covers every environment dependency required to run LinaPro from source, including Git, Go (>= 1.23), Node.js (>= 20.19), pnpm (>= 10.0), PostgreSQL (14+), Make, and the recommended AI-native workflow tools Claude Code, OpenSpec CLI, and the goframe-v2 skill. It also provides installation guidance for macOS, Linux, and Windows (WSL / Git Bash) so you can prepare your local machine before installing LinaPro.","sidebar":"quickSidebar"},"quick/have-a-try":{"id":"quick/have-a-try","title":"Try It Out","description":"This guide walks through a complete article management CRUD source plugin example to demonstrate LinaPro\'s AI-native development flow, including requirement exploration with the spec-driven workflow, proposal generation, AI-driven implementation, service startup and functional verification, and change archival. It helps developers experience the core development model of an AI-native framework.","sidebar":"quickSidebar"},"quick/installation":{"id":"quick/installation","title":"Installation","description":"How to install and initialize LinaPro in a few minutes \u2014 cloning the repository, configuring the database connection, initializing the database schema, loading demo data, and starting the development service. Complete the environment setup before cloning.","sidebar":"quickSidebar"},"quick/overview":{"id":"quick/overview","title":"Overview","description":"A comprehensive introduction to LinaPro \u2014 its background, architecture, and core capabilities. LinaPro is an AI-native full-stack framework built on Go + Vue 3, featuring a dual-mode plugin system, full RBAC permission management, scheduled task scheduling, live API documentation, a spec-driven AI development workflow, and a lifecycle-spanning AI skill set for building sustainable, continuously deliverable business systems.","sidebar":"quickSidebar"}}}}')}}]);